class CrateStack:
    """A last-in-first-out pile of crates."""

    def __init__(self):
        self._crates = []

    def push(self, item):
        self._crates.append(item)

    def pop(self):
        if not self._crates:
            return None           # empty stack: no exception
        return self._crates.pop()

    def size(self):
        return len(self._crates)


def stack_run(ops):
    stack = CrateStack()
    out = []
    for op in ops:
        if op == "pop":
            out.append(stack.pop())
        elif op == "size":
            out.append(stack.size())
        else:                      # ["push", item]
            stack.push(op[1])
    return out

