exercise.solution:
class Thermostat:
    """Integer targets between MIN and MAX, inclusive."""

    MIN = 10
    MAX = 30

    def __init__(self, start):
        self.set(start)          # same validation as any later set

    def set(self, value):
        if not (self.MIN <= value <= self.MAX):
            raise ValueError("target out of range: %r" % value)
        self._target = value

    def value(self):
        return self._target


def thermostat_trace(start, ops):
    try:
        unit = Thermostat(start)
    except ValueError:
        return ["invalid start"]
    out = []
    for op in ops:
        if op[0] == "set":
            try:
                unit.set(op[1])
                out.append("ok")
            except ValueError:
                out.append("ValueError")
        else:                     # ["get"]
            out.append(unit.value())
    return out

