exercise.solution:
class Shape:
    """Base contract: every shape reports a name and an area."""

    def name(self):
        raise NotImplementedError("subclasses implement name()")

    def area(self):
        raise NotImplementedError("subclasses implement area()")


class Rectangle(Shape):
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def name(self):
        return "rectangle"

    def area(self):
        return self.width * self.height


class Square(Rectangle):
    def __init__(self, side):
        super().__init__(side, side)   # a square IS a rectangle

    def name(self):
        return "square"


class Compound(Shape):
    def __init__(self, first, second):
        self.first = first
        self.second = second

    def name(self):
        return "compound"

    def area(self):
        return self.first.area() + self.second.area()


def shape_report(specs):
    built = []
    out = []
    for i, spec in enumerate(specs):
        if spec[0] == "rect":
            shape = Rectangle(spec[1], spec[2])
        elif spec[0] == "square":
            shape = Square(spec[1])
        else:                          # ["compound", i, j]
            shape = Compound(built[spec[1]], built[spec[2]])
        built.append(shape)
        out.append(str(i) + ":" + shape.name() + "=" + str(shape.area()))
    return out

