exercise.solution:
class Version:
    """A major.minor.patch version that compares numerically."""

    def __init__(self, major, minor, patch):
        self.major = major
        self.minor = minor
        self.patch = patch

    def _key(self):
        return (self.major, self.minor, self.patch)

    def __eq__(self, other):
        return self._key() == other._key()

    def __lt__(self, other):
        return self._key() < other._key()

    def __str__(self):
        return "%d.%d.%d" % self._key()


def version_sort(specs):
    versions = []
    for spec in specs:
        parts = [int(p) for p in spec.split(".")]
        parts += [0] * (3 - len(parts))   # missing parts are zero
        versions.append(Version(parts[0], parts[1], parts[2]))
    ordered = [str(v) for v in sorted(versions)]
    distinct = []
    for v in versions:
        if not any(v == d for d in distinct):   # uses __eq__
            distinct.append(v)
    return [ordered, len(distinct)]
